boolean match(Node n, String w, int i) {
    if (n == null) return false;
    if (i == w.length()) return n.end;
    if (w.charAt(i) == '.') {
        for (Node c : n.ch) if (c != null && match(c, w, i + 1)) return true;
        return false;
    }
    return match(n.ch[w.charAt(i) - 'a'], w, i + 1);
}
